local module = {}

function module.call(handler, level, errorMessage, ...)
	local success, result = xpcall(handler, function(err)
		local errType = type(err)
		if errType == "table" then
			err = err.message or ""
		end
		local message = debug.traceback(err, level + 2)
		message = errorMessage .. "\n" .. message
		local lines = {}
		for line in message:gmatch("[^\n]+") do
			table.insert(lines, line)
		end
		message = table.concat({ unpack(lines, 1, math.min(8, #lines)) }, "\n")
		return message
	end, ...)
	if not success then
		error(result, 0)
	end
	return result
end

return module
